<template><view class="phone mine-page"><PageHeader title="我的"/><ConnectionState/><view class="mine-hero"><view class="avatar"><image src="/static/mine-white.png"/></view><view><text class="mine-name">{{isBackend?(connection.user?.displayName||connection.user?.username||'未登录'):'演示用户'}}</text><text class="small block">{{isBackend?'站点与本人订单来自平台账号':'本地演示账号'}}</text></view><text class="mine-badge">{{isBackend?'平台账号':'本地体验'}}</text></view><view class="padded-content"><view class="panel mine-stats"><view><text class="stat-value">{{state.orders.length}}</text><text>充电订单</text></view><view><text class="stat-value">{{energy(totalEnergy)}}</text><text>累计模拟电量/度</text></view><view><text class="stat-value">{{isBackend?(connection.user?'已登录':'未登录'):state.reports.length}}</text><text>{{isBackend?'账号状态':'故障反馈'}}</text></view></view><view class="panel menu-panel"><button v-if="isBackend&&!connection.user" class="menu-row" @click="go('/pages/account/index')"><text>账号登录 / 注册</text><text class="chevron">›</text></button><button v-if="isBackend&&connection.user" class="menu-row" @click="signOut"><text>退出账号</text><text class="chevron">›</text></button><button class="menu-row" @click="go('/pages/orders/index')"><image src="/static/order-active.png"/><text>我的充电订单</text><text class="chevron">›</text></button><button class="menu-row" @click="enterCode(openSocket)"><image src="/static/scan-teal.png"/><text>输入编号充电</text><text class="chevron">›</text></button><button class="menu-row" @click="go('/pages/report/index')"><image src="/static/service.png"/><text>故障报修与反馈</text><text class="chevron">›</text></button><button class="menu-row" @click="about"><image src="/static/location.png"/><text>关于本次演示</text><text class="chevron">›</text></button></view><view v-if="state.reports.length" class="panel"><view class="section-row"><text class="section-title">最近报修</text><button class="small-link" @click="go('/pages/report/index?history=1')">查看全部 ›</button></view><view v-for="r in state.reports.slice(0,3)" :key="r.id" class="report-record" @click="go('/pages/report/index?history=1')"><view class="section-row"><text>{{r.socketCode}}</text><text class="tag">{{r.status==='resolved'?'已处理':r.status==='processing'?'处理中':'待处理'}}</text></view><text class="muted small">{{r.description}}</text></view></view><DemoNotice/><text class="attribution">电动自行车智能充电管理系统<br/>Smart E-Bike Charging Management System</text></view><BottomNav current="mine"/></view></template>
<script setup>
import {computed} from 'vue';import {onShow} from '@dcloudio/uni-app';import ConnectionState from '../../components/ConnectionState.vue';import PageHeader from '../../components/PageHeader.vue';import BottomNav from '../../components/BottomNav.vue';import DemoNotice from '../../components/DemoNotice.vue';import {state,go,enterCode,openSocket,isBackend,connection,refreshData,logout} from '../../store.js';import {energy} from '../../domain/charging.mjs';
const totalEnergy=computed(()=>state.orders.some(o=>o.energyWh===null)?null:state.orders.reduce((n,o)=>n+o.energyWh,0));
onShow(()=>refreshData());
const signOut=()=>uni.showModal({title:'退出账号',content:'是否退出当前账号？',success:r=>{if(r.confirm)logout();}});
const about=()=>uni.showModal({title:'电动自行车智能充电管理系统',content:isBackend?'用户端通过平台账号读取站点与本人订单，提供插座选择、充电与报修功能；实际可用功能以服务端接口为准。真实设备控制与第三方支付尚未接入。':'提供地图找站、插座选择、六种充电方式、订单计费与报修。本地演示使用模拟业务数据，H5 和小程序分别存储；联网模式通过统一业务后端运行，尚未接入真实设备与第三方支付。',showCancel:false});
</script>
